// Find smallest cube expressible as sum of two different positive cubes in two different ways
// We need: n^3 = a^3 + b^3 = c^3 + d^3

const maxN = 5000;
const sums = new Map();

// Build all possible sums of two different positive cubes
for (let a = 1; a <= maxN; a++) {
  let a3 = a * a * a;
  for (let b = a + 1; b <= maxN; b++) {
    let sum = a3 + b * b * b;
    if (!sums.has(sum)) {
      sums.set(sum, []);
    }
    sums.get(sum).push([a, b]);
  }
}

// Find which ones have at least 2 different representations AND are perfect cubes
let results = [];
for (let [sum, pairs] of sums) {
  if (pairs.length >= 2) {
    // Check if sum is a perfect cube
    let root = Math.round(Math.pow(sum, 1/3));
    if (root * root * root === sum) {
      results.push({cube: sum, root: root, pairs: pairs});
    }
  }
}

results.sort((a, b) => a.cube - b.cube);

console.log("Found:", results.length);
if (results.length > 0) {
  console.log("Smallest:");
  console.log(`Cube: ${results[0].cube}`);
  console.log(`Root: ${results[0].root}`);
  console.log(`Representations:`);
  for (let pair of results[0].pairs) {
    console.log(`  ${pair[0]}^3 + ${pair[1]}^3`);
  }
}

